1	//! Source file management.
2	
3	use std::fmt::{self, Debug, Formatter};
4	use std::ops::Range;
5	use std::sync::Arc;
6	
7	use typst_utils::LazyHash;
8	
9	use crate::lines::Lines;
10	use crate::reparser::reparse;
11	use crate::{FileId, LinkedNode, Span, SpanNumber, SubRange, SyntaxNode, parse};
12	
13	/// A Typst source file containing the full source text, a mapping from byte
14	/// indices to lines/columns, and the parsed syntax tree.
15	///
16	/// All line and column indices start at zero, just like byte indices. Only for
17	/// user-facing display, you should add 1 to them.
18	///
19	/// Values of this type are cheap to clone and hash.
20	#[derive(Clone, Hash)]
21	pub struct Source(Arc<LazyHash<SourceInner>>);
22	
23	/// The internal representation of a [`Source`].
24	#[derive(Clone, Hash)]
25	struct SourceInner {
26	    id: FileId,
27	    root: SyntaxNode,
28	    lines: Lines<String>,
29	}
30	
31	impl Source {
32	    /// Create a new source file. This parses the input text and assigns span
33	    /// numbers to the parsed tree.
34	    pub fn new(id: FileId, text: impl Into<String>) -> Self {
35	        let text: String = text.into();
36	        #[cfg(feature = "timing")]
37	        let _scope = typst_timing::TimingScope::new("create source");
38	        let mut root = parse(&text);
39	        root.numberize(id, Span::FULL).unwrap();
40	        Self(Arc::new(LazyHash::new(SourceInner { id, lines: Lines::new(text), root })))
41	    }
42	
43	    /// Create a new source file with an already created syntax tree.
44	    pub fn with_root(id: FileId, text: String, root: SyntaxNode) -> Self {
45	        Self(Arc::new(LazyHash::new(SourceInner { id, lines: Lines::new(text), root })))
46	    }
47	
48	    /// The root node of the file's untyped syntax tree.
49	    pub fn root(&self) -> &SyntaxNode {
50	        &self.0.root
51	    }
52	
53	    /// The id of the source file.
54	    pub fn id(&self) -> FileId {
55	        self.0.id
56	    }
57	
58	    /// The whole source as a string slice.
59	    pub fn text(&self) -> &str {
60	        self.0.lines.text()
61	    }
62	
63	    /// An acceleration structure for conversion of UTF-8, UTF-16 and
64	    /// line/column indices.
65	    pub fn lines(&self) -> &Lines<String> {
66	        &self.0.lines
67	    }
68	
69	    /// Fully replace the source text.
70	    ///
71	    /// This performs a naive (suffix/prefix-based) diff of the old and new text
72	    /// to produce the smallest single edit that transforms old into new and
73	    /// then calls [`edit`](Self::edit) with it.
74	    ///
