    let leaf = LinkedNode::new(source.root()).leaf_at(6, Side::Before).unwrap();
    let prev = leaf.prev_leaf().unwrap();
    assert_eq!(leaf.leaf_text(), "fun");
    assert_eq!(prev.leaf_text(), "set");

