pub(super) fn unexpected(&mut self) {
    self.convert_to_error(eco_format!("unexpected {}", self.kind().name()));
}

/// Assign spans to each node.
pub(super) fn numberize(
    &mut self,
    id: FileId,
    within: Range<u64>,
) -> NumberingResult {
    if within.start >= within.end {
        Err(Unnumberable)
    } else if let Some(inner) = self.data.inner_mut() {
        inner.numberize(Some(&mut self.span), id, None, within)
    } else {
        self.span =
            Span::from_number(id, SpanNumber((within.start + within.end) / 2));
        Ok(())
    }
}

